WIDGET_SRC = "import 'dart:math' as math;\n\nimport 'package:audio_session/audio_session.dart';\nimport 'package:flutter/cupertino.dart';\nimport 'package:flutter/material.dart';\nimport 'package:flutter/services.dart';\nimport 'package:just_audio/just_audio.dart';\nimport 'package:provider/provider.dart';\n\nimport '../models/radio_station.dart';\nimport '../providers/radio_provider.dart';\nimport '../providers/theme_provider.dart';\n\n/// 주사위 판에 올릴 방송 하나\nclass DiceStation {\n  final RadioStation station;\n  final String badge; // 로고 칸 글자 (KBS·MBC 등)\n  final String frequency; // 93.1 MHz (없으면 '')\n  /// 지금 하는 프로그램 이름 (편성표가 없으면 '')\n  final String Function(RadioProvider radio) program;\n\n  const DiceStation({\n    required this.station,\n    required this.badge,\n    this.frequency = '',\n    required this.program,\n  });\n}\n\n/// 라디오 주사위: 가운데 포인트 색 판에 주사위를 던지고, 멈추면 판 위에 방송이 나오며 바로 재생\nFuture<void> showRadioDice(BuildContext context, List<DiceStation> pool) {\n  if (pool.isEmpty) return Future.value();\n  return showGeneralDialog(\n    context: context,\n    barrierDismissible: false,\n    barrierColor: const Color(0x8C0A0907),\n    transitionDuration: const Duration(milliseconds: 250),\n    pageBuilder: (ctx, _, __) => _DiceBoard(pool: pool),\n    transitionBuilder: (ctx, a, _, child) => FadeTransition(\n      opacity: a,\n      child: ScaleTransition(\n        scale: Tween(begin: 0.92, end: 1.0).animate(CurvedAnimation(parent: a, curve: Curves.easeOutCubic)),\n        child: child,\n      ),\n    ),\n  );\n}\n\n// ───────── 주사위 소리 (효과음 설정을 따름: 무음·진동 모드에선 폰이 알아서 소리를 끔) ─────────\nclass _DiceSound {\n  static AudioPlayer? _p;\n\n  static Future<void> play(BuildContext context) async {\n    bool on = true;\n    try {\n      on = context.read<ThemeProvider>().feedbackSoundEnabled;\n    } catch (_) {}\n    if (!on) return;\n    // 바닥에 닿을 때마다 짧은 진동\n    for (final ms in const [290, 690, 940]) {\n      Future.delayed(Duration(milliseconds: ms), () {\n        const MethodChannel('kr.ssing.catsong/media').invokeMethod('vibrate').catchError((Object _) => null);\n      });\n    }\n    try {\n      _p ??= AudioPlayer(handleInterruptions: false, handleAudioSessionActivation: false);\n      await _p!.setAndroidAudioAttributes(const AndroidAudioAttributes(\n        contentType: AndroidAudioContentType.sonification,\n        usage: AndroidAudioUsage.assistanceSonification,\n      ));\n      await _p!.setAsset('assets/dice_roll.mp3');\n      await _p!.seek(Duration.zero);\n      _p!.play();\n    } catch (_) {}\n  }\n}\n\n// ───────── 판 ─────────\nclass _DiceBoard extends StatefulWidget {\n  final List<DiceStation> pool;\n  const _DiceBoard({required this.pool});\n\n  @override\n  State<_DiceBoard> createState() => _DiceBoardState();\n}\n\nclass _DiceBoardState extends State<_DiceBoard> with TickerProviderStateMixin {\n  static const double _w = 292, _h = 360, _d = 84;\n  static String? _lastName; // 방금 나온 방송은 빼기\n  static List<int> _faceBag = []; // 1~6 한 바퀴씩\n  static int _lastFace = 0;\n\n  late final AnimationController _throw =\n      AnimationController(vsync: this, duration: const Duration(milliseconds: 1050));\n  late final AnimationController _out =\n      AnimationController(vsync: this, duration: const Duration(milliseconds: 300));\n  late final AnimationController _info =\n      AnimationController(vsync: this, duration: const Duration(milliseconds: 350));\n\n  final _rng = math.Random();\n  bool _busy = false;\n  DiceStation? _cur;\n  // 멈출 때 각도\n  double _rx = 0, _ry = 0, _rz = 0;\n  int _spin = 0;\n\n  @override\n  void initState() {\n    super.initState();\n    WidgetsBinding.instance.addPostFrameCallback((_) => _roll());\n  }\n\n  @override\n  void dispose() {\n    _throw.dispose();\n    _out.dispose();\n    _info.dispose();\n    super.dispose();\n  }\n\n  DiceStation _pick() {\n    var list = widget.pool.where((s) => s.station.name != _lastName).toList();\n    if (list.isEmpty) list = widget.pool;\n    final p = list[_rng.nextInt(list.length)];\n    _lastName = p.station.name;\n    return p;\n  }\n\n  int _nextFace() {\n    if (_faceBag.isEmpty) {\n      _faceBag = [1, 2, 3, 4, 5, 6]..shuffle(_rng);\n      if (_faceBag.first == _lastFace) _faceBag.add(_faceBag.removeAt(0));\n    }\n    _lastFace = _faceBag.removeAt(0);\n    return _lastFace;\n  }\n\n  Future<void> _roll() async {\n    if (_busy) return;\n    _busy = true;\n    final pick = _pick();\n    final face = _nextFace();\n    final t = _faceTarget[face]!;\n    _spin += 2;\n    final tilt = math.pi / 180;\n    _rx = t.$1 + (_rng.nextBool() ? 7 : -7) * tilt + 2 * math.pi * _spin;\n    _ry = t.$2 + (_rng.nextBool() ? 8 : -8) * tilt + 2 * math.pi * (_spin + 1);\n    _rz = (_rng.nextDouble() * 30 - 15) * tilt;\n    setState(() => _cur = null);\n    _info.value = 0;\n    _out.value = 0;\n    _throw.forward(from: 0);\n    _DiceSound.play(context);\n    // 던지기 1초 + 멈춘 채로 1초 보여주기\n    await Future.delayed(const Duration(milliseconds: 1050 + 1000));\n    if (!mounted) return;\n    await _out.forward(from: 0); // 쏙 사라짐\n    if (!mounted) return;\n    setState(() => _cur = pick);\n    context.read<RadioProvider>().playStation(pick.station);\n    _info.forward(from: 0);\n    _busy = false;\n  }\n\n  void _close() {\n    if (_busy) return;\n    Navigator.of(context).pop();\n  }\n\n  // 위아래 통통 (0~1 → 판 안 위쪽 좌표)\n  double _bounceTop(double t) {\n    const k = [(0.0, -60.0), (0.28, 130.0), (0.48, 72.0), (0.66, 130.0), (0.80, 110.0), (0.90, 130.0), (1.0, 130.0)];\n    for (var i = 1; i < k.length; i++) {\n      if (t <= k[i].$1) {\n        final a = k[i - 1], b = k[i];\n        final f = (t - a.$1) / (b.$1 - a.$1);\n        return a.$2 + (b.$2 - a.$2) * f;\n      }\n    }\n    return 130;\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final point = context.watch<ThemeProvider>().primaryColor;\n    return GestureDetector(\n      behavior: HitTestBehavior.opaque,\n      onTap: _close, // 판 바깥 누르면 닫기 (라디오는 계속)\n      child: Center(\n        child: GestureDetector(\n          onTap: () {}, // 판 안은 닫히지 않게\n          child: SizedBox(\n            width: _w,\n            height: _h,\n            child: ClipRRect(\n              borderRadius: BorderRadius.circular(26),\n              child: Material(\n                type: MaterialType.transparency,\n                child: Stack(\n                  children: [\n                    Positioned.fill(child: RepaintBoundary(child: CustomPaint(painter: _FeltPainter(point)))),\n                    // 제목 (던지는 동안만)\n                    Positioned(\n                      top: 22,\n                      left: 0,\n                      right: 0,\n                      child: AnimatedOpacity(\n                        duration: const Duration(milliseconds: 250),\n                        opacity: _cur == null ? 0.8 : 0,\n                        child: const Text('어느 방송이 나올까요?',\n                            textAlign: TextAlign.center,\n                            style: TextStyle(color: Colors.white, fontSize: 12.5, fontWeight: FontWeight.w700)),\n                      ),\n                    ),\n                    // 주사위 + 그림자\n                    AnimatedBuilder(\n                      animation: Listenable.merge([_throw, _out]),\n                      builder: (context, _) {\n                        final t = _throw.value;\n                        final xf = const Cubic(0.2, 0.6, 0.3, 1).transform(t);\n                        final rf = const Cubic(0.15, 0.6, 0.25, 1).transform(t);\n                        final left = -90 + (((_w - _d) / 2) + 90) * xf;\n                        final top = _bounceTop(t);\n                        final out = Curves.easeInCubic.transform(_out.value);\n                        final shadowOpacity = ((0.15 + 0.75 * ((top + 60) / 190).clamp(0.0, 1.0)) * (1 - out)).toDouble();\n                        return Stack(\n                          children: [\n                            Positioned(\n                              left: left + 7,\n                              top: 130 + _d - 8,\n                              child: Opacity(\n                                opacity: shadowOpacity.clamp(0.0, 1.0).toDouble(),\n                                child: Container(\n                                  width: 70,\n                                  height: 14,\n                                  decoration: BoxDecoration(\n                                    borderRadius: BorderRadius.circular(10),\n                                    boxShadow: const [BoxShadow(color: Color(0x73000000), blurRadius: 8)],\n                                  ),\n                                ),\n                              ),\n                            ),\n                            Positioned(\n                              left: left,\n                              top: top,\n                              child: Opacity(\n                                opacity: 1 - out,\n                                child: Transform.scale(\n                                  scale: 1 - 0.8 * out,\n                                  child: DiceCube(size: _d, rx: _rx * rf, ry: _ry * rf, rz: _rz * rf),\n                                ),\n                              ),\n                            ),\n                          ],\n                        );\n                      },\n                    ),\n                    // 판 위 방송\n                    if (_cur != null)\n                      Positioned.fill(\n                        child: FadeTransition(\n                          opacity: _info,\n                          child: SlideTransition(\n                            position: Tween(begin: const Offset(0, 0.03), end: Offset.zero)\n                                .animate(CurvedAnimation(parent: _info, curve: Curves.easeOutCubic)),\n                            child: _StationInfo(item: _cur!, onAgain: _roll),\n                          ),\n                        ),\n                      ),\n                    // ✕\n                    Positioned(\n                      top: 12,\n                      right: 12,\n                      child: GestureDetector(\n                        behavior: HitTestBehavior.opaque,\n                        onTap: _close,\n                        child: const SizedBox(\n                          width: 36,\n                          height: 36,\n                          child: Icon(Icons.close_rounded, color: Color(0xCCFFFFFF), size: 20),\n                        ),\n                      ),\n                    ),\n                  ],\n                ),\n              ),\n            ),\n          ),\n        ),\n      ),\n    );\n  }\n}\n\n// 면이 앞으로 오게 하는 각도 (rx, ry)\nconst Map<int, (double, double)> _faceTarget = {\n  1: (0.0, 0.0),\n  6: (0.0, -math.pi),\n  2: (0.0, -math.pi / 2),\n  5: (0.0, math.pi / 2),\n  3: (-math.pi / 2, 0.0),\n  4: (math.pi / 2, 0.0),\n};\n\n/// 판 위에 나온 방송\nclass _StationInfo extends StatelessWidget {\n  final DiceStation item;\n  final VoidCallback onAgain;\n  const _StationInfo({required this.item, required this.onAgain});\n\n  @override\n  Widget build(BuildContext context) {\n    final radio = context.watch<RadioProvider>();\n    final program = item.program(radio);\n    final fav = radio.isFavorite(item.station.stationUuid);\n    return Padding(\n      padding: const EdgeInsets.fromLTRB(22, 54, 22, 22),\n      child: Column(\n        children: [\n          Container(\n            width: 72,\n            height: 72,\n            alignment: Alignment.center,\n            decoration: BoxDecoration(\n              color: Colors.white.withOpacity(0.18),\n              borderRadius: BorderRadius.circular(20),\n              border: Border.all(color: Colors.white.withOpacity(0.45), width: 1.5),\n            ),\n            child: Text(item.badge,\n                maxLines: 1,\n                overflow: TextOverflow.ellipsis,\n                style: const TextStyle(color: Colors.white, fontSize: 17, fontWeight: FontWeight.w800)),\n          ),\n          const SizedBox(height: 14),\n          Text(item.station.name,\n              maxLines: 1,\n              overflow: TextOverflow.ellipsis,\n              style: const TextStyle(\n                  color: Colors.white, fontSize: 19, fontWeight: FontWeight.w800, letterSpacing: -0.4)),\n          const SizedBox(height: 4),\n          Row(\n            mainAxisAlignment: MainAxisAlignment.center,\n            children: [\n              const _MiniBars(),\n              const SizedBox(width: 6),\n              Text(item.frequency.isEmpty ? '지금 재생 중' : '지금 재생 중 · ${item.frequency}',\n                  style: TextStyle(color: Colors.white.withOpacity(0.85), fontSize: 12.5)),\n            ],\n          ),\n          if (program.isNotEmpty) ...[\n            const SizedBox(height: 14),\n            Container(\n              width: double.infinity,\n              padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 9),\n              decoration: BoxDecoration(\n                color: Colors.black.withOpacity(0.18),\n                borderRadius: BorderRadius.circular(12),\n              ),\n              child: Column(\n                children: [\n                  Text('지금 하는 프로그램',\n                      style: TextStyle(color: Colors.white.withOpacity(0.7), fontSize: 10.5)),\n                  const SizedBox(height: 1),\n                  Text(program,\n                      maxLines: 1,\n                      overflow: TextOverflow.ellipsis,\n                      style: const TextStyle(color: Colors.white, fontSize: 13, fontWeight: FontWeight.w700)),\n                ],\n              ),\n            ),\n          ],\n          const Spacer(),\n          Row(\n            children: [\n              Expanded(\n                child: _BoardButton(\n                  filled: true,\n                  onTap: () {\n                    const MethodChannel('kr.ssing.catsong/media').invokeMethod('vibrate');\n                    onAgain();\n                  },\n                  icon: Icons.casino_outlined,\n                  label: '다시 던지기',\n                ),\n              ),\n              const SizedBox(width: 8),\n              Expanded(\n                child: _BoardButton(\n                  filled: false,\n                  onTap: () {\n                    const MethodChannel('kr.ssing.catsong/media').invokeMethod('vibrate');\n                    radio.toggleFavorite(item.station);\n                  },\n                  icon: fav ? CupertinoIcons.heart_fill : CupertinoIcons.heart,\n                  label: '즐겨찾기',\n                ),\n              ),\n            ],\n          ),\n        ],\n      ),\n    );\n  }\n}\n\nclass _BoardButton extends StatelessWidget {\n  final bool filled;\n  final VoidCallback onTap;\n  final IconData icon;\n  final String label;\n  const _BoardButton({required this.filled, required this.onTap, required this.icon, required this.label});\n\n  @override\n  Widget build(BuildContext context) {\n    final fg = filled ? const Color(0xFF17140F) : Colors.white;\n    return Material(\n      color: filled ? Colors.white : Colors.white.withOpacity(0.18),\n      borderRadius: BorderRadius.circular(13),\n      child: InkWell(\n        borderRadius: BorderRadius.circular(13),\n        onTap: onTap,\n        child: SizedBox(\n          height: 44,\n          child: Row(\n            mainAxisAlignment: MainAxisAlignment.center,\n            children: [\n              Icon(icon, size: 17, color: fg),\n              const SizedBox(width: 6),\n              Text(label, style: TextStyle(color: fg, fontSize: 13, fontWeight: FontWeight.w800)),\n            ],\n          ),\n        ),\n      ),\n    );\n  }\n}\n\n/// 재생 중 작은 막대 3개\nclass _MiniBars extends StatefulWidget {\n  const _MiniBars();\n  @override\n  State<_MiniBars> createState() => _MiniBarsState();\n}\n\nclass _MiniBarsState extends State<_MiniBars> with SingleTickerProviderStateMixin {\n  late final AnimationController _c =\n      AnimationController(vsync: this, duration: const Duration(milliseconds: 1000))..repeat();\n\n  @override\n  void dispose() {\n    _c.dispose();\n    super.dispose();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return SizedBox(\n      height: 11,\n      child: AnimatedBuilder(\n        animation: _c,\n        builder: (_, __) => Row(\n          mainAxisSize: MainAxisSize.min,\n          crossAxisAlignment: CrossAxisAlignment.end,\n          children: [\n            for (var i = 0; i < 3; i++) ...[\n              if (i > 0) const SizedBox(width: 2),\n              Container(\n                width: 2.5,\n                height: 3 + 8 * (0.5 + 0.5 * math.sin(_c.value * 2 * math.pi + i * 1.3)),\n                decoration: BoxDecoration(color: Colors.white, borderRadius: BorderRadius.circular(1)),\n              ),\n            ],\n          ],\n        ),\n      ),\n    );\n  }\n}\n\n/// 입체 주사위 (그림 파일 없이 코드로)\nclass DiceCube extends StatelessWidget {\n  final double size, rx, ry, rz;\n  const DiceCube({super.key, required this.size, this.rx = 0, this.ry = 0, this.rz = 0});\n\n  static final Map<int, Matrix4> _faceRot = {\n    1: Matrix4.identity(),\n    6: Matrix4.rotationY(math.pi),\n    2: Matrix4.rotationY(math.pi / 2),\n    5: Matrix4.rotationY(-math.pi / 2),\n    3: Matrix4.rotationX(math.pi / 2),\n    4: Matrix4.rotationX(-math.pi / 2),\n  };\n  static const Map<int, List<int>> _pips = {\n    1: [4],\n    2: [0, 8],\n    3: [0, 4, 8],\n    4: [0, 2, 6, 8],\n    5: [0, 2, 4, 6, 8],\n    6: [0, 2, 3, 5, 6, 8],\n  };\n\n  @override\n  Widget build(BuildContext context) {\n    final rot = Matrix4.identity()\n      ..rotateZ(rz)\n      ..rotateX(rx)\n      ..rotateY(ry);\n    final faces = <Widget>[];\n    for (final e in _faceRot.entries) {\n      final m = rot.clone()..multiply(e.value);\n      final facing = m.entry(2, 2); // 1 = 정면, 0 이하 = 뒤쪽\n      if (facing <= 0.02) continue; // 안 보이는 면은 안 그림\n      final full = Matrix4.identity()\n        ..setEntry(3, 2, 0.0013)\n        ..multiply(m)\n        ..translate(0.0, 0.0, -size / 2);\n      faces.add(Transform(\n        alignment: Alignment.center,\n        transform: full,\n        child: _face(e.key, facing),\n      ));\n    }\n    return SizedBox(width: size, height: size, child: Stack(children: faces));\n  }\n\n  Widget _face(int n, double light) {\n    final pip = size * 0.18;\n    final c = Color.lerp(const Color(0xFFC9C2B6), const Color(0xFFFBF8F2), light.clamp(0.0, 1.0))!;\n    return Container(\n      width: size,\n      height: size,\n      padding: EdgeInsets.all(size * 0.15),\n      decoration: BoxDecoration(\n        color: c,\n        borderRadius: BorderRadius.circular(size * 0.2),\n        border: Border.all(color: const Color(0x14000000), width: 1),\n      ),\n      child: Stack(\n        children: [\n          for (final k in _pips[n]!)\n            Align(\n              alignment: Alignment(-1.0 + (k % 3), -1.0 + (k ~/ 3)),\n              child: Container(\n                width: n == 1 ? pip * 1.4 : pip,\n                height: n == 1 ? pip * 1.4 : pip,\n                decoration: BoxDecoration(\n                  color: n == 1 ? const Color(0xFFD9473C) : const Color(0xFF17140F),\n                  shape: BoxShape.circle,\n                ),\n              ),\n            ),\n        ],\n      ),\n    );\n  }\n}\n\n/// 포인트 색 천 (가운데 밝게 + 잔잔한 결 + 바느질 점선)\nclass _FeltPainter extends CustomPainter {\n  final Color color;\n  _FeltPainter(this.color);\n\n  @override\n  void paint(Canvas canvas, Size size) {\n    final rect = Offset.zero & size;\n    final hsl = HSLColor.fromColor(color);\n    final light = hsl.withLightness((hsl.lightness + 0.08).clamp(0.0, 1.0)).toColor();\n    final dark = hsl.withLightness((hsl.lightness - 0.16).clamp(0.0, 1.0)).toColor();\n    canvas.drawRect(\n      rect,\n      Paint()\n        ..shader = RadialGradient(\n          center: const Alignment(0, -0.15),\n          radius: 0.9,\n          colors: [light, color, dark],\n          stops: const [0, 0.5, 1],\n        ).createShader(rect),\n    );\n    // 천 결: 작은 점 (항상 같은 모양)\n    final r = math.Random(11);\n    final dot = Paint();\n    for (var i = 0; i < 1600; i++) {\n      dot.color = (r.nextBool() ? Colors.white : Colors.black).withOpacity(0.035 + r.nextDouble() * 0.04);\n      canvas.drawCircle(Offset(r.nextDouble() * size.width, r.nextDouble() * size.height), 0.6 + r.nextDouble() * 0.7, dot);\n    }\n    // 바느질 점선\n    final inner = RRect.fromRectAndRadius(rect.deflate(10), const Radius.circular(18));\n    final path = Path()..addRRect(inner);\n    final stroke = Paint()\n      ..color = Colors.white.withOpacity(0.28)\n      ..style = PaintingStyle.stroke\n      ..strokeWidth = 1.4;\n    for (final metric in path.computeMetrics()) {\n      var d = 0.0;\n      while (d < metric.length) {\n        canvas.drawPath(metric.extractPath(d, d + 5), stroke);\n        d += 9;\n      }\n    }\n  }\n\n  @override\n  bool shouldRepaint(_FeltPainter old) => old.color != color;\n}\n\n/// 라디오 처음 들어왔을 때 한 번만: 가운데 큰 주사위 카드\nclass RadioDiceIntro extends StatefulWidget {\n  final VoidCallback onThrow;\n  final VoidCallback onClose;\n  const RadioDiceIntro({super.key, required this.onThrow, required this.onClose});\n\n  @override\n  State<RadioDiceIntro> createState() => _RadioDiceIntroState();\n}\n\nclass _RadioDiceIntroState extends State<RadioDiceIntro> with SingleTickerProviderStateMixin {\n  late final AnimationController _c =\n      AnimationController(vsync: this, duration: const Duration(milliseconds: 6000))..repeat();\n\n  @override\n  void dispose() {\n    _c.dispose();\n    super.dispose();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final isDark = context.watch<ThemeProvider>().isDarkMode;\n    final bg = isDark ? const Color(0xFF32302C) : const Color(0xFFF4EFE5);\n    final ink = isDark ? const Color(0xFFF3EFE7) : const Color(0xFF17140F);\n    final onInk = isDark ? const Color(0xFF24221F) : const Color(0xFFF4EFE5);\n    final hint = isDark ? const Color(0xFFB8B0A2) : const Color(0xFF8A8378);\n    return Stack(\n      children: [\n        Positioned.fill(child: Container(color: bg.withOpacity(0.35))),\n        Center(\n          child: GestureDetector(\n            onTap: widget.onThrow,\n            child: Container(\n              width: 214,\n              padding: const EdgeInsets.fromLTRB(18, 26, 18, 18),\n              decoration: BoxDecoration(\n                color: bg.withOpacity(0.94),\n                borderRadius: BorderRadius.circular(28),\n                boxShadow: [BoxShadow(color: Colors.black.withOpacity(0.14), blurRadius: 30, offset: const Offset(0, 10))],\n              ),\n              child: Stack(\n                clipBehavior: Clip.none,\n                children: [\n                  Column(\n                    mainAxisSize: MainAxisSize.min,\n                    children: [\n                      AnimatedBuilder(\n                        animation: _c,\n                        builder: (_, __) {\n                          final s = math.sin(_c.value * 2 * math.pi);\n                          return Padding(\n                            padding: const EdgeInsets.symmetric(vertical: 8),\n                            child: DiceCube(\n                              size: 72,\n                              rx: (-16 - 3 * s) * math.pi / 180,\n                              ry: (22 * s) * math.pi / 180 + 0.0001,\n                            ),\n                          );\n                        },\n                      ),\n                      const SizedBox(height: 14),\n                      Text('뭐 들을지 고민될 땐',\n                          style: TextStyle(color: ink, fontSize: 15, fontWeight: FontWeight.w800)),\n                      const SizedBox(height: 3),\n                      Text('주사위를 던져 보세요', style: TextStyle(color: hint, fontSize: 12.5)),\n                      const SizedBox(height: 14),\n                      Container(\n                        padding: const EdgeInsets.symmetric(horizontal: 18, vertical: 9),\n                        decoration: BoxDecoration(color: ink, borderRadius: BorderRadius.circular(999)),\n                        child: Text('던져 보기',\n                            style: TextStyle(color: onInk, fontSize: 12.5, fontWeight: FontWeight.w800)),\n                      ),\n                    ],\n                  ),\n                  Positioned(\n                    top: -16,\n                    right: -8,\n                    child: GestureDetector(\n                      behavior: HitTestBehavior.opaque,\n                      onTap: widget.onClose,\n                      child: SizedBox(\n                        width: 36,\n                        height: 36,\n                        child: Icon(Icons.close_rounded, size: 18, color: hint),\n                      ),\n                    ),\n                  ),\n                ],\n              ),\n            ),\n          ),\n        ),\n      ],\n    );\n  }\n}\n"
